import json, pathlib

BASE = pathlib.Path('/workspace/data_upgrades')

def w(stage, examples):
    p = BASE / f"upgrade_{stage}.jsonl"
    with open(p, "w") as f:
        for ex in examples:
            f.write(json.dumps({"messages":[{"role":"user","content":ex[0]},{"role":"assistant","content":ex[1]}]}) + "\n")
    print(f"Wrote {len(examples)} examples → {p}")

# ── Stage BR: Stock market fundamentals ──────────────────────────────────────
br = [
("What is a stock exchange and how does it work?","A stock exchange is a regulated marketplace where buyers and sellers trade shares of publicly listed companies. Major exchanges: NYSE (New York), NASDAQ (tech-heavy), LSE (London), TSE (Tokyo). Mechanism: Orders are matched electronically via a central limit order book (CLOB). Market makers provide liquidity by quoting bid/ask prices. Companies list shares via IPO to raise capital. Post-IPO, shares trade between investors — the company receives no proceeds from secondary trading. Exchanges enforce listing standards (minimum market cap, reporting requirements, governance rules)."),
("What is the difference between a stock and a bond?","Stock (equity): Ownership share in a company. Holder benefits from price appreciation and dividends. Last in line if company liquidates — highest risk, highest potential return. Bond (debt): Loan to a company or government. Holder receives fixed interest (coupon) payments and principal at maturity. Senior to equity in liquidation — lower risk, lower return. Key differences: Bonds have defined maturity; stocks do not. Bond income is contractual; dividends are discretionary. Bondholders are creditors; stockholders are owners. During bankruptcy: bondholders paid first, equity often wiped out."),
("What is market capitalisation and why does it matter?","Market capitalisation = share price × total shares outstanding. Categories: Mega-cap (>$200B): Apple, Microsoft — stable, liquid. Large-cap ($10B–$200B): established companies, lower volatility. Mid-cap ($2B–$10B): growth potential, moderate risk. Small-cap ($300M–$2B): higher growth/risk. Micro-cap (<$300M): speculative, illiquid. Why it matters: Determines index membership (S&P 500 requires large-cap). Indicates company size and stability. Affects institutional investor eligibility. Used to calculate portfolio weightings in passive funds."),
("Explain the difference between a market order and a limit order.","Market order: Execute immediately at best available price. Guarantees execution, not price. Risk: slippage in volatile or illiquid markets — you may pay more/receive less than expected. Limit order: Execute only at a specified price or better. Buy limit: triggers at or below limit price. Sell limit: triggers at or above limit price. Guarantees price, not execution — order may not fill if price never reaches limit. Stop order: triggers a market order when price reaches stop level. Stop-limit: triggers a limit order at stop level — avoids slippage but may not execute. Use market orders for liquid stocks where speed matters; limit orders for precise entry/exit."),
("What is an IPO and how does the process work?","IPO (Initial Public Offering): Company sells shares to public investors for the first time. Process: 1. Select underwriters (investment banks) — typically Goldman, Morgan Stanley, etc. 2. Due diligence and SEC filing (Form S-1) — full financial disclosure. 3. Roadshow — management presents to institutional investors. 4. Book building — underwriters gauge demand, set IPO price. 5. Allocation — shares distributed to institutional investors first. 6. First day of trading — retail investors can buy on open market. Underwriters take 3–7% spread. Lock-up period (typically 180 days) prevents insiders selling immediately. IPOs often pop on day one then underperform long-term — retail investors rarely get IPO price allocation."),
("What are dividends and how do they work?","Dividends: Distribution of company profits to shareholders. Types: Cash dividend (most common), stock dividend (additional shares), special dividend (one-time). Key dates: Declaration date — board announces dividend. Ex-dividend date — must own shares before this date to receive dividend. Record date — company confirms shareholder list. Payment date — dividend paid. Dividend yield = annual dividend / share price. Payout ratio = dividends / net income — high ratio may be unsustainable. Dividend reinvestment (DRIP): automatically buys more shares. Growth investors often prefer companies reinvesting profits over paying dividends. Dividends taxed as ordinary income or qualified rate depending on holding period."),
("What is the P/E ratio and how is it used?","P/E (Price-to-Earnings) ratio = share price / earnings per share (EPS). Measures how much investors pay per dollar of earnings. High P/E: market expects high future growth (tech stocks often 30–60×). Low P/E: value stock or declining business (utilities often 10–15×). Forward P/E uses projected earnings — more forward-looking. Trailing P/E uses last 12 months — backward-looking. PEG ratio = P/E / earnings growth rate — adjusts for growth. Limitations: Meaningless for loss-making companies. Affected by accounting choices. Sector-dependent — compare within industry. Manipulation via share buybacks (reduces shares, inflates EPS). Use alongside P/B, EV/EBITDA, and free cash flow yield for complete picture."),
("What is short selling and what are the risks?","Short selling: Borrowing shares, selling them, hoping to buy back cheaper later. Profit = sale price − repurchase price − borrowing cost. Example: Borrow 100 shares at $50, sell for $5,000. Price falls to $30, buy back for $3,000. Profit: $2,000 (minus fees). Risks: Unlimited loss potential — stock can rise infinitely. Short squeeze: heavily shorted stock rises sharply, forcing shorts to cover at a loss (GameStop 2021). Borrowing costs can be high for hard-to-borrow stocks. Dividends: short seller must pay dividends to lender. Broker can recall shares at any time. Regulatory restrictions in some markets. Used by hedge funds for hedging and speculation. Retail access via put options instead of direct short."),
("What is the difference between common and preferred stock?","Common stock: Voting rights at shareholder meetings. Dividends paid after preferred but share in upside fully. Last claim on assets in liquidation. Most publicly traded shares are common. Preferred stock: Fixed dividend (like a bond) — paid before common. Priority in liquidation over common. Usually no voting rights. May be convertible to common shares. Types: cumulative (missed dividends accumulate), participating (extra dividends if profits high), perpetual vs. redeemable. Preferred stock trades more like bonds — price sensitive to interest rates. Common gives more upside; preferred gives more protection and income. Institutions and VCs often hold preferred in private companies."),
("What is an index fund and how does it differ from active management?","Index fund: Passively tracks a market index (S&P 500, FTSE 100, etc.). Buys all (or representative sample of) constituent stocks proportionally. Benefits: Very low fees (0.03–0.20% expense ratio). Broad diversification. Outperforms most active managers over 10+ years (S&P SPIVA data: ~90% of active funds underperform benchmark after fees over 15 years). No manager risk. Active fund: Manager selects stocks to beat benchmark. Higher fees (0.5–2%+ expense ratio). Requires consistent outperformance to justify cost. Most fail to beat index after fees long-term. ETFs vs mutual funds: ETFs trade intraday on exchange; mutual funds priced once daily at NAV. Recommendation for most investors: low-cost index ETFs (Vanguard, iShares, SPDR)."),
("What drives stock prices up or down?","Fundamental drivers: Earnings (EPS growth is primary long-term driver). Revenue growth and margin expansion. Macroeconomic conditions — interest rates, inflation, GDP growth. Industry tailwinds/headwinds. Sentiment/technical drivers: Investor expectations vs. reality — price moves on surprise, not absolutes. News flow (earnings beats/misses, product launches, regulatory action). Short-term: fund flows, retail buying pressure, momentum. Long-term: earnings and free cash flow. Interest rates: Higher rates → bonds more attractive → stocks less attractive → lower P/E multiples. Rate cuts → opposite. Currency effects: multinational companies affected by FX moves. Supply/demand: index inclusion, buybacks, insider buying, large block trades."),
("What is a stock split and why do companies do them?","Stock split: Company increases share count while proportionally reducing share price. 2-for-1 split: 100 shares at $200 → 200 shares at $100. Total value unchanged. Reverse split: Opposite — reduces shares, increases price per share. Why companies split: Lower price increases retail accessibility (psychological barrier). Improves liquidity — more shares trading. Signal of confidence (usually done after strong price appreciation). S&P 500 index inclusion considerations. Famous splits: Apple 4-for-1 in 2020, Tesla 3-for-1 in 2022. Reverse splits often signal distress — done to avoid delisting (minimum price requirements). Neither split creates nor destroys value — purely mechanical."),
("Explain the concept of beta in stocks.","Beta measures a stock's volatility relative to the market (benchmark, usually S&P 500). Beta = 1.0: Moves in line with market. Beta > 1.0: More volatile than market. Tech stocks often 1.3–1.8. Beta < 1.0: Less volatile. Utilities, consumer staples often 0.4–0.7. Beta < 0: Moves opposite to market (rare). Gold miners sometimes negative beta. Calculated via regression of stock returns vs. market returns over 2–5 years. Limitations: Historical — doesn't predict future volatility. Doesn't capture idiosyncratic risk (company-specific events). Low beta ≠ safe investment (a declining company can have low beta). Use beta for portfolio construction and expected volatility modelling, not as standalone metric."),
("What is the difference between growth and value investing?","Growth investing: Targets companies with above-average revenue/earnings growth. Pays premium valuation (high P/E, P/S). Bets on future potential over current earnings. Examples: Amazon (loss-making for years), Tesla, Nvidia. Risks: High valuations mean severe drawdowns if growth disappoints. Value investing (Benjamin Graham, Warren Buffett): Seeks undervalued stocks — trading below intrinsic value. Low P/E, P/B ratios. Often mature companies with stable earnings. Value trap risk: cheap for a reason (declining industry). Historically: value outperformed long-term; growth dominated 2010–2021; value recovered 2022+. Blend investing combines both. Key: both can work — what matters is buying below intrinsic value regardless of label."),
("What are ETFs and how do they work?","ETF (Exchange-Traded Fund): Basket of securities (stocks, bonds, commodities) that trades on an exchange like a single stock. Structure: Fund holds underlying assets. Authorised participants (large banks) create/redeem shares in large blocks (creation units) by delivering underlying assets. Arbitrage mechanism keeps ETF price close to NAV. Types: Equity (SPY tracks S&P 500), Bond (AGG), Commodity (GLD), Sector (XLK tech), Thematic (ARKK innovation), Inverse (SH short S&P 500), Leveraged (TQQQ 3× NASDAQ). Advantages: Intraday trading, tax efficiency, low cost, diversification. Risks: Leveraged/inverse ETFs decay over time — not suitable for buy-and-hold. Illiquid ETFs have wide spreads. Synthetic ETFs use derivatives — counterparty risk."),
("What is short interest and what does high short interest signal?","Short interest: Total number of shares sold short as percentage of float (shares available for trading). High short interest (>20%): Many investors betting stock will fall. Can indicate fundamental problems, but also creates short squeeze potential. Short interest ratio (days to cover) = short interest / average daily volume. High days-to-cover = shorts need many days to exit — higher squeeze risk. Short squeeze mechanics: Bad news bet fails, price rises. Shorts rush to cover (buy back shares). Buying pressure accelerates price rise. Other shorts forced to cover — feedback loop. GameStop (Jan 2021): >100% short interest, retail coordinated via Reddit, shorts lost billions. Short interest data published twice monthly by FINRA. High short interest alone is not a buy signal — requires catalyst to trigger squeeze."),
("What is earnings per share (EPS) and how is it calculated?","EPS = (Net income − preferred dividends) / weighted average shares outstanding. Basic EPS: Uses actual shares outstanding. Diluted EPS: Includes all potential shares (options, convertibles, warrants) — more conservative. Adjusted/non-GAAP EPS: Strips out one-time items — often used in earnings calls. Example: Net income $500M, 100M shares → EPS = $5.00. Why it matters: Primary driver of stock price long-term. Earnings growth drives P/E expansion or compression. EPS beat/miss vs. analyst consensus moves price on earnings day. EPS manipulation: Share buybacks reduce denominator → EPS rises even if net income flat. GAAP vs. non-GAAP gap can be revealing. Always read actual earnings report, not just headlines."),
("Explain the concept of market breadth.","Market breadth measures how many stocks participate in a market move — gauges health of a rally or decline. Indicators: Advance-Decline Line (A/D): Cumulative sum of (advancing stocks − declining stocks). Rising A/D in bull market = broad participation = healthy trend. Divergence: Index at new high but A/D declining = narrow rally, warning sign. New Highs/New Lows ratio: More stocks at 52-week highs than lows = bullish breadth. McClellan Oscillator: Short-term breadth momentum indicator. Percentage of stocks above 200-day MA: <20% = oversold market, >80% = extended. Key rule: Bull markets built on breadth are sustainable. Rallies driven by 5–10 mega-cap stocks (as in 2023 Magnificent Seven) are fragile. Breadth divergences often precede market tops."),
("What is a circuit breaker in stock markets?","Circuit breakers: Automatic trading halts triggered when markets fall sharply — designed to prevent panic-driven crashes. US equity market circuit breakers (triggered by S&P 500 decline): Level 1: −7% → 15-minute halt (before 3:25pm ET). Level 2: −13% → 15-minute halt (before 3:25pm ET). Level 3: −20% → trading halted for remainder of day. Individual stock circuit breakers (LULD): Trading halted if price moves >5–20% within 5 minutes depending on price tier. History: Introduced after 1987 Black Monday crash. Triggered during COVID crash (March 2020) — multiple days of circuit breakers. Individual stock halts common on earnings days or news events. Criticism: May amplify panic by confirming severity; futures markets continue trading during equity halts."),
("What is the difference between bull and bear markets?","Bull market: Sustained rise of ≥20% from recent lows. Characterised by rising investor confidence, economic expansion, increasing corporate profits. Average bull market: +177% gain, lasts ~5.5 years (S&P 500 historical). Bear market: Decline of ≥20% from recent highs. Driven by recession fears, earnings contraction, rising rates, geopolitical events. Average bear market: −36% decline, lasts ~9.7 months. Correction: −10% to −20% — shorter-lived, common even in bull markets. Secular bull/bear: Multi-decade trend (secular bull 1982–2000, secular bear 1966–1982). Cyclical bull/bear: Within secular trend. Key: Bear markets are shorter but feel longer psychologically. Investors who stay invested through bear markets capture full bull market recovery. Time in market beats timing the market."),
("What is a stock buyback and how does it affect share price?","Buyback (share repurchase): Company uses cash to buy its own shares on open market, reducing shares outstanding. Effect on EPS: Net income same ÷ fewer shares = higher EPS → often drives P/E expansion. Effect on price: Direct buying support. Signal: Management believes stock is undervalued (positive signal). Tax advantage: No immediate tax for shareholders vs. dividends. Critics: Uses capital that could fund R&D or capex. Masks declining earnings. Debt-funded buybacks risky. S&P 500 companies bought back ~$800B–$1T annually in 2021–2023. Apple alone: $90B+ per year in buybacks. 2023: US introduced 1% excise tax on buybacks. Buybacks benefit long-term shareholders (reduced dilution) but create short-term price management incentive for management."),
("What are sector ETFs and how do investors use them for rotation?","Sector ETFs track specific GICS sectors: XLF (Financials), XLK (Technology), XLE (Energy), XLV (Health Care), XLU (Utilities), XLB (Materials), XLI (Industrials), XLP (Consumer Staples), XLY (Consumer Discretionary), XLRE (Real Estate), XLC (Communication Services). Sector rotation strategy: Different sectors outperform at different economic cycle stages. Early expansion: Financials, Consumer Discretionary outperform. Late expansion: Energy, Materials, Industrials. Recession: Utilities, Consumer Staples, Health Care (defensive). Recovery: Tech, Financials. Rotation signals: Leading economic indicators, yield curve, credit spreads. Execution: Shift ETF allocation toward sectors expected to benefit from current cycle phase. Risk: Cycle timing is difficult — macro forecasters are frequently wrong."),
("Explain the concept of float and its importance for traders.","Float: Number of shares available for public trading. Float = Total shares − insider holdings − restricted stock − institutional lock-ups. Low float (<10M shares): Small supply → high volatility. Large price moves on modest volume. Prone to short squeezes and pump-and-dump. Hard to take large positions without moving price. High float (>500M shares): More liquid, stable. Large institutional investors can enter/exit without excessive slippage. Examples: Apple float: ~15.4B shares — extremely liquid. Meme stocks: Often low float — why GameStop moved so violently. Float rotation: When new shares issued (secondary offering) or insiders sell, float increases — dilutive, often negative for price. Traders use float to estimate volatility and size positions appropriately."),
("What is the VIX and how is it used?","VIX (CBOE Volatility Index): Market's expectation of S&P 500 volatility over next 30 days. Calculated from S&P 500 options prices — specifically implied volatility. Called 'fear gauge.' VIX levels: <15: Low volatility, complacent market. 15–25: Normal range. 25–35: Elevated anxiety, increased uncertainty. >35: High fear — crash or major event (COVID March 2020: VIX hit 85). VIX and market relationship: VIX spikes when markets fall — negative correlation. VIX is mean-reverting — always returns to ~20 long-term. Trading the VIX: VIX futures, VIX options, VXX ETF (tracks short-term VIX futures — suffers from contango decay). Strategy: Buy stocks when VIX >40 (fear peak often near market bottom). Key: VIX measures expected volatility, not direction. High VIX = wide daily swings, not necessarily continued decline."),
]

# ── Stage BS: Trading strategies & technical analysis ───────────────────────
bs = [
("What is technical analysis and what are its core assumptions?","Technical analysis (TA): Studying price charts and volume to forecast future price movements. Core assumptions: 1. Market discounts everything — price reflects all known information. 2. Prices move in trends — trending is persistent until disruption. 3. History repeats — patterns recur because human psychology is consistent. Key tools: Chart patterns, trend lines, support/resistance, moving averages, oscillators, volume analysis. TA vs. fundamental analysis: FA focuses on intrinsic value; TA focuses on price behaviour. TA more useful for timing entry/exit; FA for stock selection. Criticisms: Subjective pattern recognition, self-fulfilling prophecy, random walk hypothesis. Most professional traders use both: FA to select what to trade, TA to determine when."),
("Explain support and resistance levels.","Support: Price level where buying interest historically prevents further decline. Acts as a floor. Resistance: Price level where selling pressure historically prevents further advance. Acts as a ceiling. Key principle — role reversal: Once broken, support becomes resistance and vice versa. Why they work: Psychological anchoring — traders remember round numbers and prior highs/lows. Unfilled orders accumulate at key levels. Strength factors: More touches = stronger level. Higher volume at level = stronger. Longer time frame = more significant. Types: Horizontal S/R (prior highs/lows), dynamic S/R (moving averages, trend lines), psychological (round numbers: $100, $1,000). Trading application: Buy near support, sell near resistance. Enter on confirmed break with volume. Set stop just below support (long) or above resistance (short)."),
("What is a moving average and how is it used in trading?","Moving average (MA): Average closing price over N periods — smooths price to reveal trend direction. Simple MA (SMA): Equal weight to all periods. 200-day SMA = long-term trend. 50-day SMA = medium-term trend. 20-day SMA = short-term trend. Exponential MA (EMA): More weight on recent prices — faster reaction. Signals: Price above MA → uptrend. Price below MA → downtrend. MA crossover: 50-day crosses above 200-day = Golden Cross (bullish). 50-day crosses below 200-day = Death Cross (bearish). MA as dynamic support/resistance: Price often pulls back to MA in trending markets. Limitations: Lagging indicator — confirms trend, doesn't predict it. Whipsaws in sideways markets. Use with momentum indicators to filter false signals."),
("What is RSI and how do traders use it?","RSI (Relative Strength Index): Momentum oscillator measuring speed and magnitude of price changes. Range: 0–100. Formula: RSI = 100 − (100 / (1 + RS)), where RS = average gain / average loss over 14 periods. Overbought: RSI > 70 → potential reversal or pause. Oversold: RSI < 30 → potential bounce or reversal. Trend trading adjustment: In strong uptrend, RSI stays 40–80. In downtrend, RSI stays 20–60. Divergence (most powerful signal): Bullish divergence: Price makes lower low, RSI makes higher low → momentum improving → potential reversal up. Bearish divergence: Price makes higher high, RSI makes lower high → momentum weakening → potential reversal down. RSI alone not sufficient — combine with trend, support/resistance, volume for higher probability trades."),
("Explain MACD and how it signals buy/sell opportunities.","MACD (Moving Average Convergence Divergence): Trend-following momentum indicator. Components: MACD line = 12-period EMA − 26-period EMA. Signal line = 9-period EMA of MACD line. Histogram = MACD line − signal line. Signals: Crossover: MACD crosses above signal line → bullish. MACD crosses below signal line → bearish. Zero line cross: MACD crosses above 0 → trend turned bullish. MACD crosses below 0 → trend turned bearish. Histogram: Bars growing → momentum building. Bars shrinking → momentum weakening. Divergence: Price trend diverges from MACD → potential reversal. Best used in trending markets — generates many false signals in choppy conditions. Combine with RSI and volume for confirmation. Standard settings (12,26,9) can be adjusted for faster/slower signals."),
("What is a trend line and how do you draw one correctly?","Trend line: Straight line connecting a series of highs or lows to identify trend direction. Uptrend line: Connect two or more higher lows. Upward sloping. Acts as support — buy on touch. Downtrend line: Connect two or more lower highs. Downward sloping. Acts as resistance — sell on touch. Rules for valid trend line: Minimum two points to draw, three points to confirm. Don't force lines — connect actual price pivots, not body midpoints. Steeper trend lines are less sustainable (>45° breaks more often). Trend line break: Close below uptrend line = potential trend change. Requires confirmation — volume spike, follow-through. Channel: Two parallel trend lines containing price (upper resistance, lower support). Trading channel: Buy lower line, sell upper line, or trade breakout. Trend lines are subjective — different traders draw differently. Use higher time frames for more reliable lines."),
("What is volume and why is it important in trading?","Volume: Number of shares (or contracts) traded in a period. Most important confirmation tool in technical analysis. Principles: Volume confirms price moves — high volume breakout = strong conviction. Low volume breakout = weak, likely to fail. Volume precedes price — unusual volume often signals coming move. Buying vs. selling volume: Price up + high volume = strong buying. Price up + low volume = weak rally (bearish divergence). Price down + high volume = strong selling. Price down + low volume = weak selling (bullish divergence). Volume indicators: OBV (On-Balance Volume): Cumulative volume — add on up days, subtract on down days. OBV divergence is powerful signal. Volume profile: Shows volume at each price level — high-volume nodes = strong S/R. VWAP (Volume-Weighted Average Price): Institutional benchmark — price trades above/below VWAP matters for institutions."),
("Explain the head and shoulders pattern.","Head and shoulders (H&S): Reversal pattern signalling trend change from bullish to bearish. Formation: Left shoulder: Rally, partial pullback. Head: Higher rally, deeper pullback. Right shoulder: Rally that fails to reach head's high, then declines. Neckline: Line connecting lows of the two pullbacks. Signal: Break below neckline with volume = confirmed sell signal. Target: Neckline − (Head height − Neckline). Example: Neckline at $50, head at $70 → target = $50 − $20 = $30. Inverse H&S: Same pattern upside down = bullish reversal. Right shoulder volume: Should be lower than left shoulder on H&S top — declining enthusiasm. Neckline slope: Upward-sloping neckline = stronger signal on break. Failure rate: H&S fails ~30% of time — always use stop loss above right shoulder."),
("What is Fibonacci retracement and how do traders use it?","Fibonacci retracement: Uses Fibonacci ratios (23.6%, 38.2%, 50%, 61.8%, 78.6%) to identify potential support/resistance during pullbacks. Based on Fibonacci sequence where each number is sum of prior two. Key levels: 38.2% — shallow retracement (strong trend). 50% — common retracement level (not technically Fibonacci but widely watched). 61.8% — golden ratio — strongest retracement level. 78.6% — deep retracement (trend weakening). How to draw: Swing low to swing high (for uptrend). Levels show where pullback may find support. Trading application: Wait for price to pull back to Fibonacci level, then look for reversal signals (candlestick pattern, volume, RSI). Enter at 38.2–61.8% retracement. Stop below 78.6% (or swing low). Target prior high or Fibonacci extension (127.2%, 161.8%). Confluence: Fib level + horizontal S/R + moving average = high-probability entry."),
("What is momentum trading and how does it work?","Momentum trading: Buying rising assets, selling (or shorting) falling ones — following trend until exhaustion. Core finding: Stocks that outperformed over past 3–12 months tend to continue outperforming over next 3–12 months (Jegadeesh & Titman 1993 — Nobel-recognised research). Strategies: Relative strength: Buy top quartile performers vs. sector/market. Absolute momentum: Buy asset class only when its trend is positive. Indicators used: Rate of change (ROC), RSI, MACD, ADX (trend strength). Entry timing: Enter after pullback in strong uptrend. Use MA alignment (price > 20 > 50 > 200 SMA = strong momentum). Exit: Price breaks key MA, momentum divergence, sector rotation. Risk: Momentum crashes — during market reversals, momentum stocks hit hardest. Position sizing critical — momentum portfolios need hard stops."),
("What is mean reversion trading?","Mean reversion: Assets that move far from historical average tend to revert back. Mathematical basis: Prices follow mean-reverting processes in range-bound markets. Indicators: Bollinger Bands (2 standard deviations from 20-period MA). RSI extreme readings (<20, >80). Z-score: How many standard deviations from mean. Strategies: Pairs trading: Two correlated stocks diverge — buy underperformer, short outperformer — profit on convergence. Statistical arbitrage: Quantitative version of pairs trading across many securities. Range trading: Buy at support, sell at resistance in defined range. Risk: Mean reversion fails when new trend begins — mean never reverts in breaking stocks. Can hold underwater positions for extended periods (carries gap risk). Works best in: Sideways markets, highly liquid assets, short holding periods. Less effective in: Strong trending markets, individual momentum stocks."),
("Explain the concept of risk-reward ratio in trading.","Risk-reward ratio (RRR): Compares potential profit to potential loss on a trade. RRR = (Target price − Entry) / (Entry − Stop loss). Example: Entry $50, Stop $47, Target $59. Risk = $3, Reward = $9. RRR = 3:1. Minimum acceptable RRR: 2:1 for most strategies. 1:1 requires 60%+ win rate to be profitable. Why RRR matters: Win rate of 40% with 3:1 RRR = profitable. Win rate of 60% with 1:1 RRR = break even. Expected value = (Win rate × avg profit) − (Loss rate × avg loss). A trader with 40% win rate and 3:1 RRR: EV = (0.4 × 3) − (0.6 × 1) = 0.6 per trade. Always define risk before entry. Never adjust stops wider after entry — stop loss is a pre-commitment device."),
("What is position sizing and how should traders approach it?","Position sizing: Determining how many shares/contracts to buy based on account size and risk. Fixed percentage risk model: Risk maximum 1–2% of account per trade. Example: $100,000 account, 1% risk = $1,000 max loss per trade. Trade entry $50, stop $47 ($3 risk per share). Position size = $1,000 / $3 = 333 shares. Kelly Criterion: Mathematical formula for optimal position sizing. Kelly % = Win rate − (Loss rate / Win ratio). Often halved (Half-Kelly) to reduce volatility. Volatility-adjusted sizing: Larger positions in low-volatility setups. Position sizing rules: Never risk more than 2% on single trade. Never have more than 6–8% total portfolio at risk. Reduce size after drawdowns. Scale in/out of positions rather than full commitment at once."),
("What is the difference between swing trading and day trading?","Day trading: All positions closed by end of trading day. No overnight risk. High frequency of trades (5–20+ daily). Requires real-time monitoring. Tools: Level 2 quotes, time & sales, intraday charts (1-min, 5-min, 15-min). Costs: Commissions, bid-ask spread — significant at high frequency. PDT rule (US): Accounts <$25,000 limited to 3 day trades per 5 days. Swing trading: Hold positions days to weeks. Captures larger moves — lower transaction cost relative to gain. Analyse daily/weekly charts. Less time-intensive — suitable for employed traders. Overnight risk: earnings, news events. Position trading: Weeks to months — follows major trends. Fundamental analysis more important. Which to choose: Day trading: capital-intensive, stressful, high skill threshold. Most day traders lose money. Swing trading: More accessible, time-efficient, still requires discipline."),
("Explain candlestick patterns and their significance.","Candlestick chart: Each candle shows open, high, low, close for a period. Body: Distance between open and close. Wick/shadow: High and low beyond body. Bullish candle (close > open): Often white or green. Bearish candle (close < open): Often black or red. Key single-candle patterns: Doji: Open = close. Indecision. Hammer: Small body, long lower wick — bullish reversal at bottom. Shooting star: Small body, long upper wick — bearish reversal at top. Marubozu: No wicks — strong directional conviction. Two-candle patterns: Bullish engulfing: Green candle fully engulfs prior red — bullish reversal. Bearish engulfing: Red candle fully engulfs prior green — bearish reversal. Three-candle patterns: Morning star: Red, doji, green — bullish reversal. Evening star: Opposite — bearish reversal. Key: Candlestick patterns at key S/R levels have much higher reliability."),
("What is the Average True Range (ATR) and how is it used?","ATR: Measures market volatility — average of true ranges over N periods (default 14). True range = max of: (High − Low), |High − Prior Close|, |Low − Prior Close|. High ATR: High volatility — wider price swings. Low ATR: Low volatility — price consolidating. Uses: Stop placement: Set stop 1.5–2× ATR below entry to avoid being stopped by normal noise. Position sizing: Reduce position size when ATR high (more volatile = more risk per share). Breakout filter: Volume AND price expansion beyond ATR = genuine breakout. Trend strength: ATR rising during trend = healthy trend. ATR declining = trend losing momentum. ATR-based trailing stop: Update stop to 2× ATR below current price each bar — locks in profits as price rises. ATR doesn't indicate direction — only volatility magnitude."),
("What is algorithmic trading and how does it work?","Algorithmic (algo) trading: Computer programs execute trades based on pre-defined rules automatically. Types: Execution algorithms: Break large orders into smaller pieces to minimise market impact (VWAP, TWAP execution). Statistical arbitrage: Exploit price inefficiencies between related instruments. Market making: Continuously quote bid/ask, profit from spread. High-frequency trading (HFT): Thousands of trades per second, microsecond latency. Trend following: MA crossovers, breakout systems — run systematically. Mean reversion: Automated pairs trading. Common languages: Python (backtesting), C++ (low-latency execution). Platforms: Interactive Brokers API, Alpaca, MetaTrader. Key components: Backtesting engine, risk management module, execution layer, monitoring system. Challenges: Overfitting historical data. Market regime changes. Execution slippage. Regulatory compliance. Most retail algos use Python + broker API — HFT requires co-location and custom hardware."),
("What is a trading journal and why is it essential?","Trading journal: Systematic record of all trades including entry/exit, reasoning, emotions, and outcome. What to record: Date/time, instrument, direction, entry/exit price, position size, stop/target. Pre-trade thesis: Why did you take this trade? What pattern/setup? Post-trade review: What happened? Did you follow your plan? Emotional state: Were you fearful, greedy, FOMO? P&L per trade. Why it matters: Pattern recognition in your own mistakes. Identifies: Over-trading certain times of day. Poor performance on certain setups. Emotional decisions after losses (revenge trading). Discipline tracking. Improvement: Review journal weekly. Identify three recurring mistakes. Focus next week on eliminating one. Elite traders attribute journal discipline as key differentiator. Without measurement, no improvement is possible."),
("Explain order flow and market microstructure basics.","Order flow: The actual stream of buy and sell orders entering the market — the raw material prices are made from. Market microstructure: Study of how trades execute and prices form. Key concepts: Bid-ask spread: Difference between best buy and sell offer. Tighter in liquid markets. Market makers profit from spread. Depth of book (Level 2): Shows all pending orders at each price level. Large orders (icebergs) hide true size. Tape reading / time & sales: Real-time print of every trade — size, price, direction. Imbalances: When buy orders overwhelm sell orders (or vice versa) price moves. Tools: DOM (Depth of Market), footprint charts (volume at each price within candle), delta (difference between buying and selling volume). Institutional footprints: Large block trades, unusual options activity, dark pool prints — suggest institutional activity. Why it matters: Price is set by order flow — understanding it gives edge beyond price patterns alone."),
("What is the wash sale rule and how does it affect traders?","Wash sale rule (US tax law): If you sell a security at a loss and repurchase the same or 'substantially identical' security within 30 days before or after the sale — the loss is disallowed for tax purposes. 61-day window: 30 days before + sale day + 30 days after. Disallowed loss: Added to cost basis of repurchased shares (deferred, not permanently lost). Applies to: Same stock, options on same stock, substantially identical funds. Does NOT apply to: Crypto (currently — regulatory change pending). Gains — only losses affected. Strategy implications: Plan loss harvesting at year-end carefully. Wait 31 days before re-buying sold position. Replace with similar but non-identical ETF to maintain market exposure. Traders with high turnover must track wash sales meticulously — brokers may not correctly aggregate across accounts. Consult tax professional for complex situations."),
("How do professional traders manage drawdowns?","Drawdown: Percentage decline from portfolio peak to trough. Max drawdown: Worst peak-to-trough decline in history. Professional standards: Hedge funds typically target max drawdown <15–20%. Drawdown exceeding 20–25% triggers risk review. Rules for managing drawdowns: 1. Reduce position size immediately as drawdown increases. At −5%: cut size 25%. At −10%: cut size 50%. At −15%: stop trading, review. 2. Never add to losing positions hoping for recovery (averaging down). 3. Identify cause: Was it market conditions or strategy failure? 4. Don't try to make back losses quickly — 'revenge trading' compounds drawdowns. Mathematical reality: −50% drawdown requires +100% gain to recover. −25% requires +33%. Protect capital first — profits second. Howard Marks: 'The first rule of compounding — never interrupt it unnecessarily.'"),
]

# ── Stage BT: Cryptocurrency trading ───────────────────────────────────────
bt = [
("What is cryptocurrency and how does it differ from traditional currency?","Cryptocurrency: Digital/virtual currency using cryptography for security, operating on decentralised networks (blockchains). Key differences from fiat currency: Decentralised: No central bank or government control. Bitcoin is controlled by protocol rules, not institutions. Supply: Bitcoin capped at 21M — deflationary by design. Fiat can be printed indefinitely. Settlement: Crypto transactions settle in minutes/seconds globally. Bank wires: 1–5 business days. Permissionless: Anyone with internet access can transact. No account required. Pseudonymous: Transactions public on blockchain, but identities not directly tied to addresses. Volatility: Far higher than fiat — Bitcoin has had multiple −80% drawdowns. Borderless: Same asset traded globally 24/7/365. Risks: No FDIC insurance. Hacks, scams prevalent. Regulatory uncertainty. Key insight: Crypto is simultaneously a technology, an asset class, a payment network, and a speculative instrument."),
("What is Bitcoin and why was it created?","Bitcoin (BTC): First decentralised cryptocurrency, created by pseudonymous Satoshi Nakamoto. Genesis block: January 3, 2009. Embedded headline: 'Chancellor on brink of second bailout for banks' — commentary on 2008 financial crisis. Purpose: Peer-to-peer electronic cash system without trusted third party. Solve double-spend problem without centralised authority. Mechanism: Proof-of-Work (PoW) consensus. Miners compete to solve cryptographic puzzles. Winner adds block to blockchain, earns block reward. Block reward halves every 210,000 blocks (~4 years) — halvings reduce new supply. Supply: Capped at 21M BTC. ~19.7M in circulation (2024). Last Bitcoin mined ~2140. Properties (digital gold narrative): Scarce, durable, portable, divisible (1 satoshi = 0.00000001 BTC), verifiable, decentralised. Market position: Largest crypto by market cap. 'Digital gold' store of value narrative."),
("How does blockchain technology work?","Blockchain: Distributed ledger where transactions are recorded in chronological blocks, linked cryptographically. Structure: Each block contains: Transaction data, timestamp, hash of previous block, nonce (PoW), Merkle root (hash of all transactions in block). Hash: Cryptographic fingerprint — any change to data produces completely different hash. Immutability: Changing any historical block invalidates all subsequent blocks — would require re-mining entire chain. Consensus: How nodes agree which chain is valid. PoW: Most computational work wins. PoS: Most staked value wins. Distributed: Thousands of nodes worldwide hold full copy — no single point of failure. Smart contracts (Ethereum): Self-executing code on blockchain — transactions trigger automatically when conditions met. No intermediary needed. Limitations: Scalability trilemma — can't simultaneously maximise decentralisation, security, and scalability. Bitcoin processes ~7 transactions/second vs. Visa's ~24,000."),
("What is Ethereum and how does it differ from Bitcoin?","Ethereum (ETH): Second-largest cryptocurrency. Created by Vitalik Buterin, launched 2015. Core difference: Ethereum is a programmable blockchain — a 'world computer.' Bitcoin is primarily a store of value / payment network. Smart contracts: Self-executing code deployable on Ethereum. Enable decentralised applications (dApps). Key innovations: EVM (Ethereum Virtual Machine): Runtime for smart contracts. Turing-complete — can run any computation. Gas: Computational fee paid in ETH for every operation. Prevents spam, compensates validators. DeFi (Decentralised Finance): Built on Ethereum — lending, DEXes, derivatives without banks. NFTs: ERC-721 standard — non-fungible tokens. Transition to PoS: 'The Merge' (September 2022) — switched from PoW to Proof-of-Stake. Reduced energy use 99.95%. ETH as asset: 'Ultrasound money' narrative — EIP-1559 burns portion of fees. Supply can deflate during high activity. Layer 2s (Arbitrum, Optimism, Base) scale Ethereum off-chain."),
("What are altcoins and how should traders evaluate them?","Altcoins: All cryptocurrencies except Bitcoin. Categories: Layer 1 blockchains (Ethereum, Solana, Avalanche, BNB Chain): Compete with Ethereum. Layer 2 scaling (Arbitrum, Optimism, Base, Polygon): Scale Ethereum. DeFi tokens (UNI, AAVE, MKR): Governance tokens for protocols. Utility tokens: Used within specific platforms. Memecoins (DOGE, SHIB, PEPE): No utility — pure speculation and community. Evaluation framework: Team: Doxxed (publicly known) vs. anonymous? Track record? Tokenomics: Total supply, circulating supply, inflation rate, vesting schedules, team allocation. Use case: Does it solve real problem? Existing alternatives? Technology: Audited code? Open source? Development activity (GitHub commits). Adoption: TVL (Total Value Locked), daily active users, transaction volume. Market cap vs. competitors. Red flags: Anonymous team, no audit, 80%+ tokens to insiders, no working product, unrealistic APY promises."),
("How do crypto exchanges work and what are the key differences?","Centralised Exchanges (CEX): Company-operated platforms. Custodial — exchange holds your keys/funds. Examples: Binance, Coinbase, Kraken, Bybit. High liquidity, advanced order types, fiat on-ramp. KYC/AML required. Risk: Exchange hack or insolvency (Mt. Gox 2014, FTX 2022 — billions lost). 'Not your keys, not your coins.' Decentralised Exchanges (DEX): Smart contract-based — no company controls funds. Non-custodial — you hold private keys. Examples: Uniswap, dYdX, Jupiter (Solana). AMM (Automated Market Maker): Uses liquidity pools instead of order books. Price determined by x × y = k formula. Risks: Smart contract bugs, impermanent loss for liquidity providers. Derivatives exchanges: Binance Futures, Bybit, dYdX — perpetual futures, options. Spot vs. derivatives: Spot = actual token ownership. Futures = contract on future price. CEX vs. DEX: CEX for beginners (better UX, liquidity, support). DEX for DeFi access and self-custody."),
("What are perpetual futures in crypto and how do they work?","Perpetual futures (perps): Derivatives contracts that track crypto price but never expire. Most popular trading instrument in crypto — often >70% of total volume. Mechanism: No expiry — held indefinitely. Funding rate: Mechanism to keep perp price close to spot. If perp > spot: Longs pay shorts (positive funding). If perp < spot: Shorts pay longs (negative funding). Paid every 8 hours on most exchanges. Leverage: 1× to 100× available. 10× leverage = $1,000 controls $10,000 position. Liquidation: If position moves against you past maintenance margin, position auto-liquidates. Example: 10× long BTC at $50,000. Liquidation at −10% = $45,000. Risk management: Use max 2–5× leverage. Know exact liquidation price. Set stop losses. Why perps dominate: No expiry date management. Easy to short. High liquidity. Accessible to retail globally (outside US regulatory restrictions). Key warning: High leverage + crypto volatility = rapid account liquidation."),
("What is DeFi (Decentralised Finance) and what are its key components?","DeFi: Financial services built on public blockchains — no banks, brokers, or intermediaries. Key components: DEXes (Uniswap, Curve): Trade tokens peer-to-peer via smart contracts. Lending/borrowing (Aave, Compound): Deposit crypto as collateral, borrow against it. Over-collateralised — must deposit >100% of loan value. Stablecoins: USDT, USDC (centralised), DAI (algorithmic/decentralised). Yield farming: Provide liquidity to DeFi protocols in exchange for token rewards. APYs can be 10–1,000%+ — higher APY = higher risk. Liquid staking (Lido): Stake ETH while receiving liquid token (stETH) usable in DeFi. Cross-chain bridges: Transfer assets between blockchains — historically high hack risk. Total Value Locked (TVL): Key DeFi health metric — total assets deposited in protocols. Risks: Smart contract exploits (billions lost to hacks). Rug pulls — anonymous developers abandon project, drain funds. Regulatory uncertainty. Tax complexity — every DeFi transaction may be taxable event."),
("What is on-chain analysis and how do traders use it?","On-chain analysis: Studying blockchain data to gain trading insights — all Bitcoin/Ethereum transactions are public. Key metrics: HODL waves: Distribution of Bitcoin by last movement date. Long-term holders (>1 year) accumulating = bullish. Active addresses: Unique addresses transacting daily — proxy for network usage. Exchange flows: BTC flowing into exchanges = potential sell pressure. BTC flowing out of exchanges = accumulation (removing from exchanges for storage). Miner metrics: Miner outflows (selling) vs. accumulation. Hash rate (network security). SOPR (Spent Output Profit Ratio): >1 = average coins moved at profit. <1 = loss. NUPL (Net Unrealised Profit/Loss): >0.75 = euphoria zone (historically near tops). <0 = capitulation (historically near bottoms). Whale watching: Large wallet movements. Tools: Glassnode (professional, paid), CryptoQuant, Santiment, blockchain.com explorers. On-chain is more useful for Bitcoin — Ethereum's DeFi activity adds complexity."),
("What are stablecoins and what are the risks involved?","Stablecoins: Cryptocurrencies designed to maintain stable value, usually pegged to USD. Types: Fiat-backed (centralised): USDT (Tether), USDC (Circle). Each token backed by real USD (or equivalent) in reserve. Audits verify reserves. Risk: Counterparty/reserve risk — Tether's reserve composition has been questioned. Regulatory risk. Crypto-backed (decentralised): DAI (MakerDAO). Backed by crypto collateral (ETH, etc.) at 150%+ ratio. Smart contract risk, collateral volatility risk. Algorithmic: UST (Terra/Luna) — not backed by real assets. Algorithmic mechanism to maintain peg. Terra UST collapsed May 2022: $40B wiped in 72 hours — de-peg triggered death spiral. Systemic risk: Tether (USDT) has $90B+ outstanding — a confidence loss could cascade across crypto markets. Use case: Trading (avoid crypto volatility without fiat conversion). DeFi liquidity. Cross-border payments. Best practice: Diversify across multiple stablecoins. Don't hold large amounts in algorithmic stablecoins."),
("How does Bitcoin halving affect price?","Bitcoin halving: Every 210,000 blocks (~4 years), block reward paid to miners halves. History: 2009: 50 BTC/block. 2012 halving: 25 BTC. 2016 halving: 12.5 BTC. 2020 halving: 6.25 BTC. 2024 halving: 3.125 BTC. Supply shock mechanism: New BTC entering market halves overnight. If demand constant or growing → price should rise (stock-to-flow model). Historical pattern: Each halving followed by bull market peak 12–18 months later. 2012 halving → 2013 peak (+8,000%). 2016 halving → 2017 peak (+2,800%). 2020 halving → 2021 peak (+700%). Diminishing returns: Each cycle's % gain smaller as market cap grows. Caveats: Correlation ≠ causation. Market may be forward-looking — halving often priced in before event. Macro environment matters (2022 rate hikes overwhelmed halving optimism). Miners: Revenue halved overnight → less efficient miners switch off → hash rate temporarily drops → difficulty adjustment restores equilibrium."),
("What is crypto market sentiment and how is it measured?","Sentiment: Collective mood of market participants — fear or greed drives short-term crypto price more than fundamentals. Fear & Greed Index (alternative.me): 0–100 scale. 0–25: Extreme fear (historically good buy zone). 25–50: Fear. 50–75: Greed. 75–100: Extreme greed (historically good caution/sell zone). Components: Volatility (25%), market momentum/volume (25%), social media (15%), surveys (15%), Bitcoin dominance (10%), Google trends (10%). Social metrics: Twitter/X mentions, Reddit activity, Telegram group growth. Search trends: Google Trends for 'Bitcoin' — spikes near retail FOMO tops. Funding rates: Positive (high) funding = overleveraged longs = correction risk. Negative funding = shorts dominant = potential squeeze. Open interest: Rising OI + rising price = trend healthy. Rising OI + falling price = shorts building, potential squeeze. Contrarian approach: Buy extreme fear, reduce exposure in extreme greed. Works as supplement to technical/on-chain analysis."),
("What is a crypto wallet and what are the differences between types?","Crypto wallet: Software or hardware that stores private keys — the cryptographic proof of ownership. Key concept: Crypto doesn't 'live in' wallet — it lives on blockchain. Wallet stores keys to access/move it. Types: Hot wallets (internet-connected): Software wallets: MetaMask (browser), Exodus, Trust Wallet. Convenient for DeFi and frequent trading. Risk: Malware, phishing. Exchange wallets: Funds held by exchange. Custodial — you don't hold keys. Risk: Exchange hack/insolvency. Cold wallets (offline): Hardware wallets: Ledger, Trezor. Physical device stores keys offline. Sign transactions offline, broadcast online. Best security for large holdings. Paper wallets: Private key written/printed — offline but fragile. Seed phrase (mnemonic): 12/24-word backup phrase generates all keys. NEVER share. Store offline physically. Anyone with seed phrase controls all funds. Best practice: Large holdings → hardware wallet. Trading funds → reputable CEX. DeFi → hot wallet with limited funds. Multi-sig: Requires multiple keys to authorise transactions — institutional grade security."),
("Explain liquidations in crypto derivatives trading.","Liquidation: Forced closure of a leveraged position when losses approach margin balance. Mechanism: Trader deposits margin (collateral). Takes leveraged position (e.g., 10× long BTC). Exchange calculates liquidation price where margin would be depleted. If price reaches liquidation level: Position auto-closed by exchange. Remaining margin (minus fees) returned — or lost entirely if market gaps through. Example: $1,000 margin, 10× long BTC at $50,000. Position value: $10,000. Liquidation at ~$45,000 (−10% from entry, adjusted for fees). Liquidation cascades: Large liquidations force selling → price drops → more liquidations → cascade. Crypto's high leverage amplifies this. Data: Coinglass.com tracks liquidations in real-time. Large liquidation events often mark local bottoms (forced selling exhausted). Avoiding liquidation: Use max 2–3× leverage. Set stop loss before liquidation price. Monitor funding rates. Avoid holding leveraged positions through major news events."),
("What is crypto tax treatment and what do traders need to know?","Crypto taxation (US — consult tax professional for specifics): IRS treats cryptocurrency as property, not currency. Taxable events: Selling crypto for fiat. Trading crypto-to-crypto (each swap is a taxable sale). Using crypto to buy goods/services. Receiving crypto as income (mining, staking, airdrops). Non-taxable: Buying crypto with fiat. Transferring between your own wallets. Gifting (up to annual exclusion limit). Capital gains: Short-term (<1 year): Taxed as ordinary income (10–37%). Long-term (>1 year): 0%, 15%, or 20% depending on income. DeFi complexity: Every swap, liquidity provision, yield farming harvest = potential taxable event. Tracking tools: Koinly, CoinTracker, TaxBit — import exchange history. Wash sale rule: Currently does NOT apply to crypto (unlike stocks). Can sell at loss and immediately rebuy. Cost basis methods: FIFO, LIFO, specific identification — choose strategically. Record keeping: Keep all transaction records — exchanges can close, wallets can be lost."),
("What is the difference between layer 1 and layer 2 blockchains?","Layer 1 (L1): The base blockchain. Handles its own consensus, security, and data availability. Examples: Bitcoin, Ethereum, Solana, Avalanche, BNB Chain, Cardano. Limitations: Scalability trilemma — can't simultaneously be fast, cheap, and decentralised. Ethereum: ~15 TPS, $5–100 gas fees during congestion. Layer 2 (L2): Built on top of L1. Inherits L1 security, processes transactions off-chain, posts proofs/data back to L1. Types: Rollups (dominant Ethereum scaling): Optimistic rollups (Arbitrum, Optimism, Base): Assume transactions valid. 7-day fraud proof window. Cheaper. ZK-rollups (zkSync, Starknet, Polygon zkEVM): Cryptographic validity proofs. Instant finality. Technically superior. State channels: Off-chain channels for specific counterparties (Lightning Network for Bitcoin). Sidechains (Polygon PoS): Own consensus — not fully L2. Benefits: 10–100× cheaper fees. 10–100× faster. Same security as Ethereum. Ecosystem: L2s growing rapidly — Arbitrum, Optimism, Base process more transactions than Ethereum mainnet."),
("How do crypto market cycles work?","Crypto market cycles: Historically 4-year cycles roughly aligned with Bitcoin halvings. Four phases: Accumulation: After bear market bottom. Low prices, low sentiment, low volume. Smart money accumulating. Media coverage minimal or negative. Markup (bull market): Price begins rising. Early adopters profit. Media coverage returns. Retail FOMO builds. Leverage increases. Distribution: Near cycle top. Smart money selling to retail. Euphoria, 'this time is different' narratives. Extremely high leverage, maximum optimism. Markdown (bear market): Price collapses. Crypto 'declared dead.' Capitulation events. Projects fail. Only strongest survive. Bitcoin-specific cycle triggers: Halving (supply shock) → ~12–18 months to peak. Indicators for cycle stage: NUPL, MVRV ratio, funding rates, exchange inflows, Fear & Greed extremes. Risks: Cycles are not guaranteed — macro environment (interest rates, regulation) can override. Each cycle different — diminishing returns at higher market cap. Altcoins typically follow Bitcoin with higher amplitude moves."),
("What are NFTs and what gives them value?","NFT (Non-Fungible Token): Unique digital asset on blockchain — each has distinct identity and cannot be replicated or exchanged 1:1. Technical: ERC-721 or ERC-1155 standard on Ethereum. Token ID and smart contract address uniquely identify it. Actual media (image/video) usually stored off-chain (IPFS). Token = proof of ownership record on-chain. Value drivers: Scarcity: Limited supply (10,000 Bored Apes). Community: Strong holder base creates social capital. Utility: Access to events, games, DAOs, staking rewards. Creator reputation: Established artists command premium. Speculation: 'Greater fool' — buy hoping someone pays more. 2021 peak: Bored Ape floor: $400,000+. Total NFT volume: Billions monthly. 2022–2023: 95%+ of NFT projects lost most value. Legitimate use cases beyond speculation: Digital art with royalties. Gaming assets (true ownership). Event tickets. Real-world asset tokenisation. Credentials and identity. Key warning: Most NFTs are pure speculation — buying jpeg at peak price is not investing, it's gambling."),
("What risk management rules should crypto traders follow?","Risk management for crypto: Essential given extreme volatility (Bitcoin −80% drawdowns; altcoins −95%+ common). Core rules: 1. Position sizing: Risk max 1–2% of portfolio per trade. Never go 'all in.' 2. Leverage limits: Beginners: 0× (spot only). Intermediate: Max 3×. Advanced: Max 5–10× with strict stops. 3. Stop losses: Always set before entry. Hard stop, not mental — crypto moves fast. 4. Portfolio allocation: Diversify across BTC (core), ETH (core), select altcoins. Limit any single altcoin to 5% max. 5. Exchange risk: Don't keep large amounts on exchanges. Self-custody large holdings. Diversify across exchanges. 6. Correlation awareness: All crypto highly correlated in crashes — diversifying within crypto doesn't protect against systemic sell-offs. 7. Dollar-cost averaging (DCA): Regular purchases reduce timing risk. Works well for long-term BTC/ETH accumulation. 8. Avoid: Leverage during sideways markets. Trading during low liquidity (weekends, holidays — gaps common). Chasing pumps. FOMO entries."),
("What is the role of Bitcoin dominance in crypto trading?","Bitcoin dominance (BTC.D): Bitcoin's market cap as percentage of total crypto market cap. Current range: ~40–65% (2020–2024). How traders use it: Rising BTC.D: Bitcoin outperforming altcoins. Typical in bear markets or early bull markets. Money rotating from alts to BTC (risk-off within crypto). Falling BTC.D (altseason): Altcoins outperforming Bitcoin. Typical in late bull markets. Capital flowing from BTC profits into higher-risk alts. Alt.D (altcoin dominance): 100% − BTC.D. 'Altseason': BTC.D falls rapidly, alts rally 2–10× Bitcoin's gains. Cycle pattern: Bear market → BTC.D rises (safety). BTC rallies first → BTC.D rises. Established alts (ETH) rally next → BTC.D starts falling. Small caps rally last → BTC.D lowest. Indicator use: BTC.D chart is technical — treat support/resistance normally. ETH/BTC ratio: Measures Ethereum vs. Bitcoin performance specifically. Rising ETH/BTC = altseason beginning. Caution: BTC.D can be skewed by stablecoin market cap growth."),
]

